/**
 * Task-child inherit for an authored virtual root.
 *
 * The SDK calls `resourceProviderOptions` once per child session id,
 * including nested `Task` grandchildren, and reuses that result for the
 * child runtime. Each id gets its own {@link childOverlayFs} over the
 * session union (authored tree plus `/tmp` scratch), so a child write
 * cannot clobber the parent or a sibling. The FileSystem handle is not
 * placed on the SDK request.
 *
 * Native executor overrides load on the first child. A static import
 * would pull workspace-only packages into every CLI start. The published
 * package omits that module; children then keep shell suppressed and
 * reach the same overlay through synthesized file tools.
 */
import { childOverlayFs } from "../../filesystem.js";
/**
 * Widened to `string` on purpose. A string-literal dynamic import is still
 * a static dependency, so the published declaration build would compile the
 * excluded executor module. Node and the test runner resolve this relative
 * to this file.
 */
const FILE_SYSTEM_EXECUTORS_SPECIFIER = "../../filesystem-executors.js";
export function createRootSubagentInherit(parent) {
    const overlays = new Map();
    return {
        inherit: {
            reportedWorkspacePath: "/",
            resourceProviderOptions: async (context) => {
                const overlay = childOverlayFor(overlays, parent, context.sessionId);
                return resourceFieldsForChild(overlay, await loadFileSystemExecutors());
            },
        },
        fileSystemForSession(sessionId) {
            return childOverlayFor(overlays, parent, sessionId);
        },
    };
}
export function resourceFieldsForChild(overlay, executors) {
    if (executors === undefined) {
        return { suppressDefaultShellExecutor: true };
    }
    return {
        overrideReadExecutor: executors.createFileSystemReadExecutor(overlay),
        overrideWriteExecutor: executors.createFileSystemWriteExecutor(overlay),
        overrideGrepExecutor: executors.createFileSystemGrepExecutor(overlay),
        overrideLsExecutor: executors.createFileSystemLsExecutor(overlay),
        suppressDefaultShellExecutor: true,
    };
}
async function loadFileSystemExecutors() {
    try {
        const loaded = await import(FILE_SYSTEM_EXECUTORS_SPECIFIER);
        if (!isFileSystemExecutorModule(loaded)) {
            throw new Error("filesystem executors module is missing its factories");
        }
        return loaded;
    }
    catch (error) {
        if (isMissingModule(error)) {
            return undefined;
        }
        throw error;
    }
}
function isFileSystemExecutorModule(value) {
    if (typeof value !== "object" || value === null) {
        return false;
    }
    const candidate = value;
    return (typeof candidate.createFileSystemReadExecutor === "function" &&
        typeof candidate.createFileSystemWriteExecutor === "function" &&
        typeof candidate.createFileSystemGrepExecutor === "function" &&
        typeof candidate.createFileSystemLsExecutor === "function");
}
function isMissingModule(error) {
    if (typeof error !== "object" || error === null) {
        return false;
    }
    if ("code" in error && error.code === "ERR_MODULE_NOT_FOUND") {
        return true;
    }
    return "cause" in error && isMissingModule(error.cause);
}
function childOverlayFor(overlays, parent, sessionId) {
    if (sessionId === undefined || sessionId === "") {
        return childOverlayFs(parent);
    }
    const existing = overlays.get(sessionId);
    if (existing !== undefined) {
        return existing;
    }
    const created = childOverlayFs(parent);
    overlays.set(sessionId, created);
    return created;
}
